  UPDATE "MembershipProgram" SET "benefits" = $q$[{"title":"One essential service every month","body":"One treatment from our Essential Services list is included in your membership price. Enjoy it without a second thought."},{"title":"Additional services at member prices","body":"Every further essential service is available at a lighter member price, so upgrading your routine is always easy."},{"title":"Savings across the entire menu","body":"Enjoy member prices on every treatment, including All Day Spa packages and face rituals."},{"title":"10% off retail products","body":"Save on high-quality products for your at-home care routine."}]$q$::jsonb WHERE "id" = $q$singleton$q$ AND "benefits" = $q$[{"body":"Satu layanan dari daftar Essential Services kami sudah termasuk dalam harga keanggotaan. Nikmati tanpa perlu berpikir panjang.","title":"Satu essential service setiap bulan"},{"body":"Seluruh essential service berikutnya tersedia dengan harga yang lebih ringan, jadi meningkatkan rutinitas Anda kapan saja menjadi mudah.","title":"Layanan tambahan dengan harga anggota"},{"body":"Nikmati harga khusus anggota untuk semua treatment, termasuk paket All Day Spa dan ritual wajah.","title":"Diskon untuk seluruh menu"},{"body":"Hemat saat membeli produk kualitas tinggi untuk rutinitas perawatan di rumah Anda.","title":"10% off produk retail"}]$q$::jsonb;
